SELECT i.notes 
FROM income i 
WHERE i.source = 'Fundraising' AND i.date_received = '2019-09-14';

SELECT SUM(e.cost) AS total_cost_of_pizzas
FROM expense e
WHERE e.expense_description = 'Pizza';

SELECT SUM(b.spent) AS total_spent_for_food
FROM budget b
WHERE b.category = 'Food';

SELECT SUM(e.cost) AS total_expense
FROM expense e
WHERE e.expense_date = '2019-08-20';

SELECT p.ID, (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) AS age
FROM Patient p
WHERE p.RBC < 3.5;

SELECT 
  (SELECT COUNT(*) FROM Examination e JOIN Patient p ON e.ID = p.ID WHERE p.PLT < 100) AS lower_than_normal,
  (SELECT COUNT(*) FROM Examination e JOIN Patient p ON e.ID = p.ID WHERE p.PLT > 400) AS higher_than_normal;

SELECT COUNT(DISTINCT l.ID) 
FROM Laboratory l 
WHERE l.IGG >= 2000;

SELECT team_fifa_api_id 
FROM Team_Attributes 
WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;

SELECT player_name 
FROM Player 
WHERE substr(birthday, 1, 7) = '1970-10';

SELECT lat, lng 
FROM circuits 
WHERE name = 'Australian Grand Prix';

SELECT COUNT(*) 
FROM circuits 
WHERE location = 'Adelaide' AND country = 'Australia';

SELECT SUM(CASE WHEN a.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN a.publisher_name = 'DC Comics' THEN 1 ELSE 0 END) AS difference
FROM superhero s
JOIN publisher a ON s.publisher_id = a.id;

SELECT COUNT(*) 
FROM hero_power 
WHERE hero_id = (SELECT id FROM superhero WHERE superhero_name = 'Amazo');

SELECT CAST(SUM(CASE WHEN g.gender = 'Male' THEN 1 ELSE 0 END) AS FLOAT) / CAST(SUM(CASE WHEN g.gender = 'Female' THEN 1 ELSE 0 END) AS FLOAT) AS ratio
FROM superhero s
JOIN gender g ON s.gender_id = g.id;

SELECT SUM(CASE WHEN p.publisher_name = 'DC Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN p.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) AS difference
FROM publisher p
JOIN superhero s ON p.id = s.publisher_id;

SELECT p.ViewCount 
