SELECT (COUNT(CASE WHEN strftime('%Y', v.CreationDate) = '2010' THEN 1 END) * 1.0) / 
       (COUNT(CASE WHEN strftime('%Y', v.CreationDate) = '2011' THEN 1 END)) AS ratio
FROM votes v;

SELECT SUM(CASE WHEN u.DisplayName = 'Mornington' THEN p.ViewCount ELSE 0 END) - SUM(CASE WHEN u.DisplayName = 'Amos' THEN p.ViewCount ELSE 0 END)
